 const profile=retain('actual-private-roundtrip-source-profile',jsonRoundtripCandidateProfile({dependencies:jsonMacroDependencies}));assert.equal(isJsonRoundtripCandidateProfile(profile),true);assert.equal(isJsonRoundtripCandidateProfile(structuredClone(profile)),false);assert.ok(profile.features.features.includes('float_roundtrip'));assert.equal(profile.parseAdmission,false);assert.throws(()=>jsonRoundtripCandidateProfile({dependencies:jsonMacroDependencies,compilationProfile:{values:{feature:['custom']}}}),/override/);assert.throws(()=>jsonRoundtripCandidateProfile({dependencies:structuredClone(jsonMacroDependencies)}),/sealed/);assert.equal(actualJsonCapabilityProfile({...dependencyInputs}).parseAvailable,false);
 const old=project(files('pub fn old(body:&str)->bool{serde_json::from_str::<serde_json::Value>(body).is_ok()}'));no(old,'old');const missing=project(files(portable),{jsonMacroDependencies:undefined,deriveDependencies:undefined});for(const name of ['text','binary','null_value','lazy'])no(missing,name);
 for(const [path,before,after]of [['src/translation_core.rs','pub use self::primitives::{json_parse, json_parse_bytes};',''],['src/translation_core/primitives.rs','::serde_json::from_str::<Json>(value).ok()','None']]){const input=files(portable);input[path]=input[path].replace(before,after);assert.notEqual(input[path],files(portable)[path]);for(const name of ['text','binary','null_value','lazy'])no(project(input),name);}
 const input=files('pub fn decode(body:&str)->Option<serde_json::Value>{serde_json::from_str::<serde_json::Value>(body).ok()}'),saved=input['src/lib.rs'],update=Hash.prototype.update;let calls=0;try{Hash.prototype.update=function(...args){if(!calls++){input['src/lib.rs']+='\n// changed during actual hashing';}return Reflect.apply(update,this,args);};assert.throws(()=>proposeCoreJsonParseCorpus({files:input,dependencyInputs}),/changed/);}finally{Hash.prototype.update=update;input['src/lib.rs']=saved;}assert.ok(calls>0);assert.equal(proposal(input).proposals.flatMap(row=>row.selections).length,1);
